-- 98 more companies: 73 Y Combinator companies plus 25 well-known startups that post on Ashby, and a
-- Y Combinator tag so the app can show and filter them.
--
-- Why Y Combinator: the user asked to target YC-backed companies, "especially the prominent ones" -- whatever the
-- industry, most members will have heard of them. Source of the list: the public YC company directory (via the
-- yc-oss mirror, updated daily). Candidates were the active or public YC companies that YC flags as a top company
-- or that have 120+ people and a US presence (198); each one's public Greenhouse, Lever and Ashby boards were probed,
-- identity-checked, and run through the real relevance filter. 118 of the 198 have a public board; the rest (Rippling,
-- Deel, Retool, Whatnot, ...) use their own systems or non-guessable board names and are not here. Companies whose
-- name check was ambiguous (Tempo, Weave, a second "Apollo") were left out.
--
-- Identity: Greenhouse boards self-report company_name (the fetcher refuses a mismatching posting; config.board_name
-- holds the board's own spelling where it differs from the display name, e.g. "HackerRank Careers"). Lever and Ashby
-- postings carry no company name, so each was checked by hand that sampled posting descriptions name the company.
--
-- Tiers (per-company cap 25/15/10/5 for tiers 0-3): tier 1 = OpenAI, Ramp, Plaid, Notion, DoorDash, Kalshi, Perplexity, Cursor, Harvey,
-- Saronic, Oklo; tier 2 = YC top companies and other well-known names; tier 3 = the rest. Admins can change any of them.
--
-- company_yc also tags 20 companies that were already tracked (exact-name matches to the YC directory, reviewed
-- by hand: Airbnb, Stripe, Coinbase, Dropbox, Instacart, ...). Alloy, Guild and Prophet matched by name only
-- and are NOT YC companies, so they are not tagged.
create table if not exists company_yc (
  company_name text primary key,
  yc_batch text not null,       -- short form: W12, S19, X25
  yc_slug text,                 -- ycombinator.com/companies/<slug>
  created_at timestamptz not null default now()
);
comment on table company_yc is 'Companies backed by Y Combinator, keyed by the exact name jobs.company carries. Public YC directory data.';
alter table company_yc enable row level security;
create policy "company_yc_select_authenticated" on company_yc for select using (auth.role() = 'authenticated');
grant select on company_yc to authenticated;

select
  v.company || ' (' || v.label || ')', 'employer_api', 'approved', true,
  'Polled with every other ' || v.platform_name || ' company on the batched schedule.',
  false,
  'Do not store full job description text -- same policy as every ' || v.platform_name || ' source in this app.',
  false,
  v.notes,
  v.config::jsonb
