on conflict (company_name) do nothing;

on conflict (company_name) do nothing;

-- Capacity. Greenhouse is fetched in batches (stalest first) and every enabled company has to come round inside the
-- 26-hour coverage window: 14 per 2 hours is 168 a day, which is below the ~210 Greenhouse companies there now.
-- 20 per 2 hours is 240 a day. Ashby runs hourly in batches of 8 (192 a day) rather than 14 every 2 hours: a first
-- fetch of a big board inserts up to 150 jobs, and smaller batches keep one invocation well inside the Edge
-- Function limit (the all-at-once Greenhouse run was killed by it).
select cron.unschedule('fetch-greenhouse-companies-batch');
select cron.schedule(
  'fetch-greenhouse-companies-batch',
  '17 */2 * * *',
  $$
  select net.http_post(
    url := 'https://cfwbtzajnaodgqilgkqn.supabase.co/functions/v1/fetch-greenhouse-companies',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImNmd2J0emFqbmFvZGdxaWxna3FuIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODg5MTk3NTQsImV4cCI6MjEwNDQ5NTc1NH0.pMdJ5vEZXrBaVQqkqXJycjGVOF116hTvusYUsagSc7w',
      'X-Cron-Secret', (select decrypted_secret from vault.decrypted_secrets where name = 'cron_secret')
    ),
    body := '{"batch": 20}'::jsonb
  );
  $$
);

select cron.unschedule('fetch-ashby-companies-batch');
select cron.schedule(
  'fetch-ashby-companies-batch',
